import React, { useState } from "react";
import "./BudgetLimits.css";

function BudgetLimits({ spendingPriorities = {}, incomeCategory, questionnaire }) {
  const selectedCategories = Object.keys(spendingPriorities || {}).filter(
    (cat) => spendingPriorities[cat] >= 3
  );

  const [limits, setLimits] = useState({});

  const handleChange = (category, value) => {
    setLimits((prev) => ({
      ...prev,
      [category]: value,
    }));
  };

  const handleSave = async () => {
    const payload = {
      incomeCategory,
      questionnaire,
      spendingPriorities,
      budgetLimits: limits,
    };

    try {
      await fetch("http://localhost:5000/save-budget", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      });

      alert("Saved successfully");
    } catch (err) {
      alert("Server error");
    }
  };

  return (
    <div className="budget-container">
      <div className="budget-card">
        <h2 className="budget-title">Set Monthly Budget Limits</h2>

        {selectedCategories.length === 0 ? (
          <p>No categories selected</p>
        ) : (
          selectedCategories.map((category) => (
            <div key={category} className="budget-group">
              <label className="budget-label">{category}</label>
              <input
                type="number"
                className="budget-input"
                placeholder="Enter amount"
                onChange={(e) => handleChange(category, e.target.value)}
              />
            </div>
          ))
        )}

        <button className="save-button" onClick={handleSave}>
          Save Budget
        </button>
      </div>
    </div>
  );
}

export default BudgetLimits;
